// Generates src/generated/openapi.ts from the public InvoiceXML OpenAPI document.
//
// Usage: npm run generate [-- <path-or-url>]
// Default source: https://api.invoicexml.com/v1/openapi
//
// Only the schemas this package exposes are kept (the EN 16931 InvoiceDocument
// model, the create options, the validation verdict and the error body); paths
// are dropped, so the generated file carries no endpoint the package does not wrap.
import { readFile, writeFile } from "node:fs/promises";
import openapiTS, { astToString } from "openapi-typescript";

const source = process.argv[2] ?? "https://api.invoicexml.com/v1/openapi";
const target = new URL("../src/generated/openapi.ts", import.meta.url);
const roots = ["InvoiceDocument", "InvoiceOptions", "ValidationResponse", "ApiProblemDetails"];

const spec = JSON.parse(
  /^https?:/.test(source)
    ? await (await fetch(source)).text()
    : await readFile(source, "utf8"),
);
const all = spec.components.schemas;

// Keep every schema reachable from the roots.
const keep = new Set();
const walk = (name) => {
  if (keep.has(name) || !all[name]) return;
  keep.add(name);
  JSON.stringify(all[name]).replace(/#\/components\/schemas\/(\w+)/g, (_, ref) => walk(ref));
};
roots.forEach(walk);

const schemas = Object.fromEntries([...keep].sort().map((name) => [name, structuredClone(all[name])]));

// Option descriptions are written for the whole API; this package documents
// the options it supports on its own method signatures instead.
for (const property of Object.values(schemas.InvoiceOptions?.properties ?? {})) {
  delete property.description;
  for (const variant of property.oneOf ?? []) delete variant.description;
}

// These descriptions cover endpoints outside this package or server internals;
// the package documents the same types on its own exports.
delete schemas.InvoiceOptions?.description;
delete schemas.ValidationResponse?.description;
delete schemas.ApiProblemDetails?.description;
delete schemas.ApiProblemDetails?.properties?.invoiceData?.description;

const pruned = {
  openapi: spec.openapi,
  info: { title: spec.info.title, version: spec.info.version },
  paths: {},
  components: { schemas },
};

const ast = await openapiTS(pruned, { exportType: false, alphabetize: true });
const header =
  "// Generated by tools/generate-types.mjs from the InvoiceXML OpenAPI document.\n" +
  "// Do not edit by hand. Run `npm run generate` to refresh.\n\n";
await writeFile(target, header + astToString(ast));
console.log(`Wrote ${keep.size} schemas to ${target.pathname}`);
